import test from 'node:test';
import assert from 'node:assert/strict';
import {normalizeName} from '../src/normalize.js';
test('trim',()=>assert.equal(normalizeName('  Ada  '),'Ada'));
test('collapse',()=>assert.equal(normalizeName(' Ada   Lovelace '),'Ada Lovelace'));
test('empty',()=>assert.equal(normalizeName('   '),''));
test('case preserved',()=>assert.equal(normalizeName(' aDa '),'aDa'));

